SELECT ?id ?name ?tsid WHERE {
  ?id rdfs:label ?name .
  OPTIONAL { ?id ref:hasTimeseriesId ?tsid }
  FILTER(REGEX(?name, "Chiller01|CondPump02|CoolingTower02"))
}

